typedef int u128 __attribute__((mode(TI)));
extern unsigned char *batalia_span_particle_textures_ptr;

extern int func_001FA898(float);

// Spawns a particle at a position with a color and scale chosen by kind.
void spawn_span_particle(float *pos, int kind, float *vec, float scale) {
    float v[4];
    float *vp = v;
    float w[4];
    float u[4];
    unsigned char *p;
    int k2 = kind;
    int c;
    float s;
    float f20;
    int k;
    *(u128 *)v = *(u128 *)vec;
    p = create_part(0);
    if (p != 0) {
        c = 0;
        k = k2;
        f20 = 0.0f;
        s = f20;
        switch (k) {
            case 0:
                c = 0x14;
                f20 = 0.015f;
                s = random_float_between(0.01f, 1.0f);
                break;
            case 1:
                c = 0xD;
                f20 = 0.5f;
                s = random_float_between(1.0f, 5.0f);
                break;
            case 2:
                c = 0xD;
                f20 = 1.0f;
                k = 1;
                s = random_float_between(20.0f, 30.0f);
                break;
        }
        *(u128 *)w = *(u128 *)vp;
        vec_scale_to_length(w, w, s);
        ((struct PartBase *)p)->timer = k2;
        ((struct PartBase *)p)->color = ((c >> 2) << 24) | 0x606060;
        *(int *)&((struct PartBase *)p)->size = (c << 24) | 0x907070;
        ((struct PartBase *)p)->unk_09 = truncate_float_to_s32(4.0f) + 0x60;
        ((struct PartBase *)p)->blend = 0x44;
        ((struct PartBase *)p)->unk_01 = 3;
        ((struct PartBase *)p)->texture = batalia_span_particle_textures_ptr[k];
        *(u128 *)&((struct PartBase *)p)->pos = *(u128 *)pos;
        FastVecAdd(u, pos, w);
        *(u128 *)(p + 0x20) = *(u128 *)u;
        ((struct PartBase *)p)->pos.f[3] = f20;
        *(float *)(p + 0x2C) = 1.0f;
        *(u128 *)(p + 0x30) = *(u128 *)vp;
        *(float *)(p + 0x3C) = scale;
    }
}
